import{_ as d,C as s,o as c,c as g,a2 as n,G as e,j as r,a as h}from"./chunks/framework.BgSoyxN5.js";const x=JSON.parse('{"title":"Партнерство TickerForge: анализ акций и идеи | Вердикт по акции, инсайдеры, фонды и идеи","description":"TickerForge как слой данных для финансовых Telegram-каналов: проверки по компании, регулярные идеи по акциям, готовые партнерские посты, отслеживаемые ссылки в бота и измеримые пилоты.","frontmatter":{"title":"Партнерство TickerForge: анализ акций и идеи | Вердикт по акции, инсайдеры, фонды и идеи","description":"TickerForge как слой данных для финансовых Telegram-каналов: проверки по компании, регулярные идеи по акциям, готовые партнерские посты, отслеживаемые ссылки в бота и измеримые пилоты.","aside":false,"locale":"ru","alternateLocales":{"en":"/partners/stock-analysis-and-ideas","ru":"/ru/partners/stock-analysis-and-ideas"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/partners/stock-analysis-and-ideas.md","filePath":"ru/partners/stock-analysis-and-ideas.md","lastUpdated":1789293971000}'),m={name:"ru/partners/stock-analysis-and-ideas.md"},u={class:"partners-wide"},b={class:"partners-post-gallery"},k={class:"partners-wide"},_={class:"partners-post-gallery"},f={class:"partners-wide"};function v(T,a,P,q,y,C){const l=s("PartnerPageAnalytics"),i=s("PartnerChannelCta"),t=s("PartnerPostImage"),o=s("PartnerCabinetCta"),p=s("PartnerLeadForm");return c(),g("div",null,[a[0]||(a[0]=n('<h1 id="партнерство-анализ-акции-и-идеи" tabindex="-1">Партнёрство: анализ акций и идеи <a class="header-anchor" href="#партнерство-анализ-акции-и-идеи" aria-label="Permalink to &quot;Партнёрство: анализ акций и идеи&quot;">​</a></h1><p>Анализ компаний, который ваш канал может публиковать: разбор тикера, контекст по инсайдерам и фондам, регулярные идеи по акциям — с отслеживаемыми ссылками обратно в TickerForge.</p><p>Это направление только про акции и компании. Рыночная и макро-программа живет на странице <a href="/ru/partners/market-news">Рыночные новости</a>, а диагностика портфеля — на странице <a href="/ru/partners/portfolio-health">Здоровье портфеля</a>.</p><p>Начните с <strong>14 дней Standard в Review Access</strong> после рассмотрения заявки. <strong>Без обязательств публиковать.</strong> Если продукт подходит, согласуем <strong>Pilot — 1–2 тестовых поста</strong>: дадим research block и отслеживаемые ссылки. После успешного пилота обсудим <strong>Active Partner</strong>: например, 2–4 поста в месяц, referral, paid или co-branded формат.</p>',4)),e(l,{offer:"telegram_research",locale:"ru"}),a[1]||(a[1]=r("div",{class:"partners-hero-actions"},[r("a",{class:"partners-button partners-button--primary",href:"#partner-contact","data-partner-event":"cta","data-partner-option":"propose_pilot","data-analytics-placement":"partner_hero"},"Запросить 14 дней Standard"),r("a",{class:"partners-button partners-button--secondary",href:"#research-formats","data-partner-event":"cta","data-partner-option":"see_formats","data-analytics-placement":"partner_hero"},"Посмотреть оба типа постов")],-1)),e(i,{eyebrow:"Посмотрите вживую",title:"Такие же посты уже выходят в живом канале",text:"В публичном канале TickerForge выходят такие же блоки с данными, какие партнер может использовать в своих публикациях. Откройте канал перед выбором формата пилота.",cta:"Открыть канал TickerForge"}),a[2]||(a[2]=n('<p class="partners-locale-switch"><a href="/partners/stock-analysis-and-ideas" hreflang="en" data-partner-event="cta" data-partner-option="locale_en" data-analytics-placement="partner_locale_switch">Read this page in English</a></p><p class="partners-backlink">Это одно из трех направлений партнерства. <a href="/ru/partners">Все варианты партнерства</a> · <a href="/ru/partners/market-news">Рыночные новости</a> · <a href="/ru/partners/portfolio-health">Здоровье портфеля</a> · <a href="/ru/partners/requirements">Требования к партнерам</a></p><p>TickerForge - образовательное ПО для поддержки решений. Это не инвестиционная рекомендация, не сигнальный канал, не брокер и не обещание доходности.</p><h2 id="что-это-такое" tabindex="-1">Что это такое <a class="header-anchor" href="#что-это-такое" aria-label="Permalink to &quot;Что это такое&quot;">​</a></h2><p>Слой данных для постов, которые вы и так хотите писать. Ваш голос и ваш вывод остаются вашими; TickerForge дает под ними блок с данными и отслеживаемую ссылку для читателей, которые захотят проверить компанию сами.</p><p>У каждого поста своя отслеживаемая ссылка, поэтому клики, старты бота и реферальная привязка видны в Partner Cabinet.</p><h2 id="research-formats" tabindex="-1">Два типа постов <a class="header-anchor" href="#research-formats" aria-label="Permalink to &quot;Два типа постов {#research-formats}&quot;">​</a></h2><p>Всё на этой странице — одно из двух, и это не одно и то же.</p><div class="partners-wide partners-wide--cards partners-wide--duo"><div class="partners-card partners-card--linked"><span>Компанию выбираете вы</span><strong><a href="#stock-analysis">Анализ акции</a></strong><p>Вы уже знаете, о каком тикере пишете. Пост подкладывает данные под ваш собственный вывод.</p></div><div class="partners-card partners-card--linked"><span>Компанию выбирает правило</span><strong><a href="#stock-ideas">Идеи по рубрикам</a></strong><p>Фиксированное правило проходит по рынку и возвращает компании, которые его прошли, — вместе с цифрами, по которым они прошли отбор.</p></div></div><p>Одобренный партнёр генерирует форматы, которые Partner Cabinet поддерживает сегодня. Форматы с пометкой «доступно для пилотов» готовятся вместе с нами, а не одним нажатием, и спрос партнёров определяет, что станет self-serve следующим.</p><h2 id="stock-analysis" tabindex="-1">Анализ акции <a class="header-anchor" href="#stock-analysis" aria-label="Permalink to &quot;Анализ акции {#stock-analysis}&quot;">​</a></h2><p>Тикер выбираете вы; TickerForge собирает всё, что о нём известно.</p><h3 id="форматы" tabindex="-1">Форматы <a class="header-anchor" href="#форматы" aria-label="Permalink to &quot;Форматы&quot;">​</a></h3><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Вердикт по акции</strong><p>Блок по одному тикеру: качество, оценочный контекст, владельцы капитала, тайминг и риск.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Активность инсайдеров</strong><p>Открытые покупки и продажи инсайдеров по тикеру. Это данные, а не вывод за читателя.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Движения фондов</strong><p>Институциональная поддержка и потоки фондов по доступной отчётности.</p></div></div></div><h3 id="на-чем-построен-такои-пост" tabindex="-1">На чём построен такой пост <a class="header-anchor" href="#на-чем-построен-такои-пост" aria-label="Permalink to &quot;На чём построен такой пост&quot;">​</a></h3><p>Партнёрский пост — это не заголовок с тикером. Каждый собирается из того же слоя, на котором работает сам продукт, и именно этого читатель не получит из скриншота графика.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>60+ финансовых показателей на период, год и квартал.</strong> Выручка, маржинальность, денежный поток, долг, покрытие, отдача — по каждой компании и по каждому году и кварталу, что у нас есть. Изменение таким образом измеряется, а не утверждается.</li><li><strong>Сжато в один экран и раскрашено.</strong> Ценность не в том, что данные есть, а в том, что читатель видит движение год к году и квартал к кварталу, фундаментальные риски и место, где рост сменил направление, — не открывая отчётность.</li><li><strong>Детект разворота (turnaround).</strong> Начали ли квартальные цифры двигаться в обратную сторону после полосы спада — как стадия, а не как мнение.</li><li><strong>Числовой рейтинг TickerForge и его собственный 5-летний тренд.</strong> Рейтинг сравнивается со своей же 5-летней скользящей: видно, оценена компания лучше или хуже собственной истории, а не только где она стоит сегодня.</li><li><strong>Институциональные держатели по 37 отслеживаемым фондам.</strong> Не «фонд купил», а статистика по конкретной акции в фиксированном именованном наборе из 37 фондов — поэтому ответ сравним между компаниями и между кварталами.</li><li><strong>Инсайдеры — NET за 3 и 12 месяцев.</strong> Не одна заметная покупка, а покупки минус продажи по двум окнам, от людей, обязанных декларировать каждую сделку.</li></ul></div><p>Именно поэтому на это можно быстро реагировать: работа по сборке уже сделана, и аудитория видит вывод вместе с доказательствами.</p><h3 id="примеры" tabindex="-1">Примеры <a class="header-anchor" href="#примеры" aria-label="Permalink to &quot;Примеры&quot;">​</a></h3>',19)),r("div",u,[r("div",b,[e(t,{src:"/partners/examples/stock-research-sample.png",alt:"Пример партнерского поста TickerForge: вердикт по акции с качеством бизнеса, фондами, таймингом и ссылкой в бот",caption:"Вердикт по акции — так его публикует партнёр.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(t,{src:"/partners/examples/insider-activity-sample.png",alt:"Пример партнерского поста TickerForge: активность инсайдеров с чистыми покупками и продажами по тикеру",caption:"Активность инсайдеров — покупки и продажи по одному тикеру.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(t,{src:"/partners/examples/fund-moves-sample.png",alt:"Пример партнерского поста TickerForge: движения фондов с институциональной поддержкой по отчётности",caption:"Движения фондов — институциональная поддержка по отчётности.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),a[3]||(a[3]=n('<p>Оформление карточки можно доработать под стиль вашего канала — это обсуждается в рамках пилота.</p><h2 id="stock-ideas" tabindex="-1">Идеи по рубрикам <a class="header-anchor" href="#stock-ideas" aria-label="Permalink to &quot;Идеи по рубрикам {#stock-ideas}&quot;">​</a></h2><p>Компанию выбирает правило. Идея здесь — это результат фильтра с приложенным обоснованием, а не имя, которое кому-то понравилось: фиксированное правило, которое компания либо проходит, либо нет, прогнанное по тем же 60+ показателям, слою из 37 фондов и инсайдерским NET-окнам выше.</p><h3 id="форматы-1" tabindex="-1">Форматы <a class="header-anchor" href="#форматы-1" aria-label="Permalink to &quot;Форматы&quot;">​</a></h3><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Разворот (Turnaround)</strong><p>Компания, у которой квартальные показатели пошли вверх после периода спада. Это ранние признаки восстановления, а не само восстановление.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Инсайдеры покупают</strong><p>Заметные чистые покупки инсайдеров за последние месяцы — от людей, которые отчитываются по каждой сделке.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Triple Rated</strong><p>Компания, прошедшая три фиксированных порога в один день: рейтинг TickerForge, Piotroski F-Score и Altman Z-Score. О цене не говорит ничего.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Weekly Gems: рост</strong><p>Выручка, прибыль и денежный поток на TTM всё ещё двигаются в нужную сторону, и качество бизнеса под ними держится.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Weekly Gems: недооценка</strong><p>Цена ниже пригодной оценки справедливой стоимости, и причина дисконта — не сам бизнес.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Weekly Gems: владельцы</strong><p>Хорошее качество бизнеса там, где инсайдеры, отслеживаемые фонды или те и другие наращивали позицию.</p></div><div class="partners-format"><span>Доступно для пилотов</span><strong>Watchlist накопления</strong><p>Тематические подборки — крупные компании, инфраструктура эпохи AI, дивидендные истории — из скана накопления.</p></div></div></div><h3 id="чем-идея-отличается-от-наводки" tabindex="-1">Чем идея отличается от наводки <a class="header-anchor" href="#чем-идея-отличается-от-наводки" aria-label="Permalink to &quot;Чем идея отличается от наводки&quot;">​</a></h3><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Правило фиксировано и названо.</strong> Каждый формат проверяет одну конкретную вещь и говорит, какую. С правилом можно спорить — с «подборкой» спорить не о чем.</li><li><strong>Доказательства едут вместе с идеей.</strong> В посте есть те самые цифры, по которым компания прошла отбор: аудиторию не просят верить шортлисту на слово.</li><li><strong>Каждый формат называет, чего он НЕ проверяет.</strong> Формат разворота не смотрит на оценку, инсайдерский — на бизнес. Именно это удерживает идею от того, чтобы читаться как рекомендация.</li><li><strong>Одна идея на формат в неделю зарезервирована за вами</strong> — два партнёра никогда не опубликуют одну компанию на одной неделе.</li></ul></div><h3 id="примеры-1" tabindex="-1">Примеры <a class="header-anchor" href="#примеры-1" aria-label="Permalink to &quot;Примеры&quot;">​</a></h3>',8)),r("div",k,[r("div",_,[e(t,{src:"/partners/examples/turnaround-detected-sample.png",alt:"Пример партнерского поста TickerForge: разворот со стадией восстановления и скором",caption:"Разворот — со скором и стадией восстановления.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(t,{src:"/partners/examples/insider-buying-sample.png",alt:"Пример партнерского поста TickerForge: инсайдеры покупают, с контекстом чистых покупок",caption:"Инсайдеры покупают — с объёмом и характером покупок.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(t,{src:"/partners/examples/idea-triple-rated-sample.png",alt:"Пример партнерского поста TickerForge: Triple Rated с тремя порогами качества",caption:"Triple Rated — у каждого порога своя отметка на шкале.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(t,{src:"/partners/examples/idea-gems-growth-sample.png",alt:"Пример партнерского поста TickerForge: Weekly Gems рост с выручкой, прибылью и денежным потоком",caption:"Weekly Gems: рост — три линии, каждая со своим направлением.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(t,{src:"/partners/examples/idea-gems-value-sample.png",alt:"Пример партнерского поста TickerForge: Weekly Gems недооценка, цена против оценки справедливой стоимости",caption:"Weekly Gems: недооценка — цена против оценки.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(t,{src:"/partners/examples/idea-gems-ownership-sample.png",alt:"Пример партнерского поста TickerForge: Weekly Gems владельцы, активность фондов и инсайдеров",caption:"Weekly Gems: владельцы — обе стороны отчётности.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),a[4]||(a[4]=r("p",null,"Шесть форматов генерируются в кабинете одним нажатием. Нужные выберите в форме внизу страницы.",-1)),a[5]||(a[5]=r("p",null,"Ещё три формата TickerForge публикует в своём канале, но не отдаёт под именем партнёра: «Стресс баланса», «Инсайдеры продают» и «Денежный поток говорит обратное». Два из них — негативные прочтения, и публиковать «эта компания в беде» под своей подписью — другое редакционное действие, чем публиковать идею.",-1)),a[6]||(a[6]=r("div",{class:"partners-wide partners-routing-note"},[r("p",null,[r("strong",null,"Каждый формат идей — подробно."),h(" Что проверяет, чего намеренно не проверяет, как компания проходит отбор и как выглядит опубликованная карточка. Одна страница, девять форматов.")]),r("a",{class:"partners-button partners-button--primary",href:"/stock-ideas","data-partner-event":"cta","data-partner-option":"stock_ideas","data-analytics-placement":"partner_ideas_banner"},"Открыть все девять форматов идей")],-1)),e(o,{locale:"ru"}),a[7]||(a[7]=n('<h2 id="как-проходит-пилот-по-анализу-и-идеям" tabindex="-1">Как проходит пилот по анализу и идеям <a class="header-anchor" href="#как-проходит-пилот-по-анализу-и-идеям" aria-label="Permalink to &quot;Как проходит пилот по анализу и идеям&quot;">​</a></h2><div class="partners-wide partners-wide--timeline"><div class="partners-steps"><div><span>1</span><strong>Назвать формат</strong><p>В форме ниже выберите направление «Анализ акций и идеи» и форматы, которые действительно будет читать ваша аудитория.</p></div><div><span>2</span><strong>Получить партнерский доступ</strong><p>Одобренный партнер получает Standard на срок пилота, и в Telegram открывается Partner Cabinet.</p></div><div><span>3</span><strong>Сделать пост</strong><p>Сгенерировать поддерживаемый формат в кабинете или получить подготовленный пост для формата, который пока запрашивается пилотом.</p></div><div><span>4</span><strong>Опубликовать своим голосом</strong><p>Ваш анализ остается вашим; добавляются блок TickerForge, дисклеймер и ваша отслеживаемая ссылка.</p></div><div><span>5</span><strong>Измерить и решить</strong><p>Статистика в кабинете показывает результат постов; дальше вы решаете - продолжать, менять формат или остановиться.</p></div></div></div><h2 id="measurement" tabindex="-1">Как считается результат <a class="header-anchor" href="#measurement" aria-label="Permalink to &quot;Как считается результат {#measurement}&quot;">​</a></h2><p>Каждый сгенерированный пост получает короткую отслеживаемую ссылку. Сама ссылка непрозрачна — в ней не зашиты код партнёра, месяц, формат, сценарий или тикер: эти значения хранятся отдельно, как поля отчёта.</p><p>Что показывает Partner Cabinet и что именно считает каждая цифра:</p><table tabindex="0"><thead><tr><th>В кабинете</th><th>Что считается</th></tr></thead><tbody><tr><td><strong>Statistics</strong></td><td>переходы, рефералы, платящие рефералы за месяц и разбивка по типам постов</td></tr><tr><td><strong>Monthly Report</strong></td><td>XLSX за текущий или предыдущий месяц, листы Summary и Posts</td></tr><tr><td><strong>Raw clicks</strong></td><td>переходы по ссылке — не уникальные люди</td></tr><tr><td><strong>Bot starts</strong></td><td>уникальные пользователи Telegram, чей первый запуск бота пришёл из этого поста</td></tr><tr><td><strong>New referrals</strong></td><td>те, кого реферальная модель впервые привязала к вам после такого запуска</td></tr><tr><td><strong>Paid subscriptions</strong></td><td>активные платные подписки среди этих рефералов сейчас — не история платежей</td></tr></tbody></table><p>Названия в первом столбце — это подписи разделов внутри кабинета, поэтому они не переводятся.</p><h2 id="что-получает-партнер" tabindex="-1">Что получает партнёр <a class="header-anchor" href="#что-получает-партнер" aria-label="Permalink to &quot;Что получает партнёр&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list partners-feature-list--split"><li>Готовые посты с разбором компании — генерируются по запросу, а не пишутся.</li><li>Еженедельные идеи по акциям с приложенными доказательствами отбора.</li><li>Картинка и форматирование канала — пост можно переслать как есть.</li><li>Отслеживаемые ссылки внутри каждого формата.</li><li>Посты на английском или русском — переключается в кабинете.</li><li>Статистика по типам постов и месячный отчёт в XLSX.</li><li>Одна идея на формат в неделю зарезервирована за вами.</li><li>Разговор про API или собственный фид, если пилот сработал.</li></ul></div><p>Условия участия, обязательства по публикациям и правила доступа одинаковы для всех направлений и живут на странице <a href="/ru/partners/requirements">требований к партнёрам</a>.</p><h2 id="кому-подходит" tabindex="-1">Кому подходит <a class="header-anchor" href="#кому-подходит" aria-label="Permalink to &quot;Кому подходит&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list partners-feature-list--split"><li>Telegram-каналам и инвестиционным сообществам, которые разбирают отдельные компании.</li><li>Авторам в Instagram и TikTok, которым нужна аргументированная карточка акции, а не очередное мнение.</li><li>YouTube-каналам, которые начинают с компании и хотят иметь цифры до съёмки.</li><li>Авторам в LinkedIn, публикующим разбор компаний для профессиональной аудитории.</li><li>Рассылкам и Discord-группам с регулярной рубрикой идей.</li><li>Всем, кто хочет говорить о компании, не проводя вечер в её отчётности.</li></ul></div><h2 id="partner-access" tabindex="-1">Модель партнёрского доступа <a class="header-anchor" href="#partner-access" aria-label="Permalink to &quot;Модель партнёрского доступа {#partner-access}&quot;">​</a></h2><p>Первый пилот включает временный партнёрский доступ.</p><table tabindex="0"><thead><tr><th>Условие</th><th>Что это значит</th></tr></thead><tbody><tr><td><strong>Что получает партнёр</strong></td><td>доступ уровня Standard на срок пилота, обычно 30 дней, плюс готовые блоки с данными, отслеживаемые ссылки, реферальная привязка и статистика в кабинете</td></tr><tr><td><strong>Что нужно сделать</strong></td><td>Без публикаций в 14-дневном Review Access; 1–2 согласованных поста в Pilot; регулярные условия обсуждаются после успешного пилота</td></tr><tr><td><strong>Кому подходит</strong></td><td>финансовые каналы примерно от 1 000 живых подписчиков; меньшие, но вовлечённые сообщества — индивидуально</td></tr><tr><td><strong>Что считается качественным постом</strong></td><td>реальный блок TickerForge, собственный анализ автора, образовательная оговорка и отслеживаемая ссылка</td></tr><tr><td><strong>Если ритм остановился</strong></td><td>бесплатный доступ ставится на паузу и возвращается к обычному Free</td></tr></tbody></table><p>Полные условия участия и точные причины, по которым доступ заканчивается, — на странице <a href="/ru/partners/requirements">требований к партнёрам</a>.</p><h2 id="чем-tickerforge-не-является" tabindex="-1">Чем TickerForge не является <a class="header-anchor" href="#чем-tickerforge-не-является" aria-label="Permalink to &quot;Чем TickerForge не является&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>TickerForge — это не:</p><ul><li>сигнальный канал</li><li>торговый бот</li><li>брокер</li><li>личная инвестиционная рекомендация</li><li>обещание доходности</li><li>автоматическая финансовая консультация</li></ul><p>TickerForge — образовательное ПО для поддержки решений: оно помогает посмотреть на бизнес, оценку, владельцев капитала и рыночный контекст до публикации.</p></div><h2 id="partner-contact" tabindex="-1">Запросить формат анализа или идей <a class="header-anchor" href="#partner-contact" aria-label="Permalink to &quot;Запросить формат анализа или идей {#partner-contact}&quot;">​</a></h2><p>Опишите ваш канал, аудиторию и форматы, которые хотите видеть первыми. Полезные детали: ссылка на канал, размер аудитории, язык, основная тема, частота постов и первые идеи по тикерам.</p>',20)),r("div",f,[e(p,{locale:"ru",source:"partners_telegram_research","default-program":"TELEGRAM_RESEARCH"})]),a[8]||(a[8]=n('<h2 id="полезные-ссылки" tabindex="-1">Полезные ссылки <a class="header-anchor" href="#полезные-ссылки" aria-label="Permalink to &quot;Полезные ссылки&quot;">​</a></h2><ul><li><a href="/ru/partners">Все варианты партнерства</a></li><li><a href="/ru/partners/cabinet">Как работает Partner Cabinet</a></li><li><a href="/ru/partners/requirements">Требования к партнерам</a></li><li><a href="/ru/partners/market-news">Рыночные новости</a></li><li><a href="/ru/partners/portfolio-health">Здоровье портфеля</a></li><li><a href="/stock-widget">Проверка отдельной акции</a></li><li><a href="/market-widget">Рыночный виджет</a></li><li><a href="/ambassador">Амбассадорская программа</a></li></ul>',2))])}const F=d(m,[["render",v]]);export{x as __pageData,F as default};
